import React, { useState } from "react";
import { collection, getDocs, deleteDoc, doc } from "firebase/firestore";
import { FIRESTORE_DB } from "../../Database/Database";

const MigrarVentas = () => {
  const [cargando, setCargando] = useState(false);
  const [mensaje, setMensaje] = useState("");
  const [eliminadas, setEliminadas] = useState(0);

  const borrarTodasLasVentas = async () => {
    const confirmar = window.confirm(
      "⚠️ ¿Seguro que querés BORRAR TODAS las ventas?\n\nEsta acción es IRREVERSIBLE y eliminará toda la colección 'ventas'."
    );

    if (!confirmar) return;

    setCargando(true);
    setMensaje("");
    setEliminadas(0);

    try {
      const snapshot = await getDocs(collection(FIRESTORE_DB, "ventas"));

      if (snapshot.empty) {
        setMensaje("No hay ventas en la colección.");
        setCargando(false);
        return;
      }

      let contador = 0;

      for (const documento of snapshot.docs) {
        await deleteDoc(doc(FIRESTORE_DB, "ventas", documento.id));
        contador++;
      }

      setEliminadas(contador);
      setMensaje(`🧨 Todas las ventas fueron eliminadas. Total: ${contador}`);
    } catch (error) {
      console.error(error);
      setMensaje("❌ Error al borrar las ventas. Mirá la consola.");
    }

    setCargando(false);
  };

  return (
    <div style={{ padding: "2rem", maxWidth: "600px" }}>
      <h2>🧹 Borrar todas las ventas (DEV)</h2>
      <p>
        Este botón elimina todos los documentos de la colección{" "}
        <b>ventas</b>. Usar únicamente para pruebas.
      </p>

      <button
        onClick={borrarTodasLasVentas}
        disabled={cargando}
        style={{
          padding: "12px 20px",
          backgroundColor: "#c0392b",
          color: "#fff",
          border: "none",
          cursor: "pointer",
          fontSize: "16px",
          borderRadius: "6px"
        }}
      >
        {cargando ? "Borrando..." : "🧨 Borrar TODAS las ventas"}
      </button>

      {mensaje && (
        <div style={{ marginTop: "1rem", fontWeight: "bold" }}>
          {mensaje}
        </div>
      )}

      {eliminadas > 0 && (
        <div style={{ marginTop: "0.5rem" }}>
          Total eliminadas: {eliminadas}
        </div>
      )}
    </div>
  );
};
////LUEGO BORRAR ESTE COMPONENTE
export default MigrarVentas;
